<?php

/**
 * Procedures the pipeline is allowed to emit, read from the ART-DECOR extracts.
 *
 * WHY THIS EXISTS
 *   The discharge procedures in an HDR are generated by a language model
 *   together with the hospital course narrative. The model used to be asked for
 *   the SNOMED code as well, with the instruction that the code "MUST be taken
 *   from the file" at a URL. Nothing in the API call gives the model a way to
 *   open that URL - no tool is declared, no file is attached - so it invented
 *   the codes instead. 46 of the 60 code strings that reached the log could be
 *   rejected by their check digit alone; the terminology server reports several
 *   of the rest as never having existed. Where a code did exist, its meaning
 *   often did not match the term beside it, and concepts such as
 *   "Pulse oximeter (physical object)" and "Salbutamol (substance)" were filed
 *   as procedures.
 *
 *   So the model is no longer asked for codes, and no longer asked for free
 *   text either. It picks from a menu that this file builds out of the value
 *   set, and every choice is checked against the same value set on the way
 *   back. A concept that is not in the value set cannot leave the pipeline.
 *
 * THE SOURCE IS ART-DECOR, NOT A FILE OF CODES
 *   Everything here goes through lib/terminology-cache.php, which reads the
 *   artefacts that fetch-terminology.php pulled from the ART-DECOR project.
 *   There is deliberately no local list of codes: a second copy would drift,
 *   and drift in a terminology is invisible until it is wrong.
 *
 *   The binding is PROCEDURE_VALUESET below, the same OID
 *   2.16.840.1.113883.3.1937.777.100.11.5 that terminology-config.php fetches:
 *   57,709 concepts, International Edition only, semantic tags procedure and
 *   regime/therapy. Its own description notes that active status was not
 *   verified per concept, so membership here means "a procedure concept this
 *   project accepts", not "active in the current release". The replacement
 *   lookup in lib/snomed.php still runs afterwards and still has work to do.
 *
 * WHY THERE IS A MENU AND A GATE
 *   The menu is what the model sees. It cannot hold the whole value set: as
 *   code and display, 57,709 concepts are about 3.5 MB, on the order of a
 *   million tokens per stay. It is therefore a shortlist, assembled per stay
 *   from the admission reason, the discharge diagnosis and a fixed set of ward
 *   procedures - every entry resolved against the value set, never typed out
 *   here as a code.
 *
 *   The gate is what the pipeline trusts. Even with a menu in the prompt a
 *   model can answer with something that is not on it, so procedureIsKnown()
 *   is applied to whatever comes back. The menu improves the narrative, the
 *   gate is what makes the output safe, and neither replaces the other.
 *
 * Requires lib/terminology-cache.php and, through it, PHP 8 with ext-dom.
 */

declare(strict_types=1);

// The fundus is read through the ART-DECOR extracts. Included here rather
// than left to the caller, so this file works wherever it is pulled in.
include_once(__DIR__ . "/terminology-cache.php");

/**
 * Value set name as terminology-config.php stores it. Changing the binding is
 * a one-line change here; nothing else in the pipeline names it.
 */
const PROCEDURE_VALUESET = 'vs-procedures-snomed-extensional';

/**
 * How many concepts the menu may hold. Around 250 costs a few thousand tokens,
 * which prompt caching absorbs, and comfortably covers what a discharge report
 * names: across 64 generated reports the whole vocabulary was 88 concepts.
 */
const PROCEDURE_MENU_LIMIT = 250;

/**
 * Ward procedures that turn up in a discharge report whatever the admission
 * reason. These are SEARCH TERMS, not codes: each is resolved against the
 * value set, and one that does not resolve is skipped rather than guessed at.
 * Writing codes here would recreate the local list this file exists to avoid.
 *
 * The spellings are the value set's own, which is not always the obvious one:
 * the concept is "Blood gases, arterial measurement", not "Arterial blood gas
 * measurement", and "Nebulizer therapy" and "Venipuncture" carry the US
 * spelling. A term that stops resolving after a value set update is reported
 * through registerMapMissing() rather than dropped in silence.
 */
const PROCEDURE_MENU_SEED_TERMS = [
    'Plain X-ray of chest',
    'Electrocardiographic procedure',
    'Echocardiography',
    'Blood test',
    'Blood gases, arterial measurement',
    'Spirometry',
    'Pulse oximetry',
    'Oxygen therapy',
    'Administration of drug or medicament',
    'Intravenous fluid replacement',
    'Nebulizer therapy',
    'Physical examination procedure',
    'Patient education',
    'Insertion of indwelling catheter into urinary bladder',
    'Venipuncture',
    'Computed tomography of chest',
    'Ultrasonography',
    'Physical therapy procedure',
    'Wound care',
    'Taking patient vital signs',
];

// ---------------------------------------------------------------------------
// the fundus
// ---------------------------------------------------------------------------

if (!function_exists('procedureFundus')) {
    /**
     * Every procedure concept the project accepts, as code => display name.
     *
     * @return array<string,string>
     */
    function procedureFundus(): array
    {
        static $fundus = null;
        if ($fundus === null) {
            // terminology_document() throws when the extract is missing, which
            // is the right behaviour: an empty binding would turn the gate
            // below into a pass and put invented codes back into the output.
            $fundus = valueset_codes(PROCEDURE_VALUESET);
        }
        return $fundus;
    }
}

if (!function_exists('procedureNormaliseTerm')) {
    /**
     * Fold a term to the form the index is keyed by: lower case, no semantic
     * tag, punctuation and repeated whitespace collapsed. "Plain X-ray of
     * chest (procedure)", "plain x ray of chest" and "Plain X-Ray of Chest"
     * all land on the same key.
     */
    function procedureNormaliseTerm(string $term): string
    {
        $t = preg_replace('/\s*\([^()]*\)\s*$/u', '', trim($term));   // semantic tag
        $t = mb_strtolower($t, 'UTF-8');
        $t = preg_replace('/[^\p{L}\p{N}]+/u', ' ', $t);              // punctuation
        return trim(preg_replace('/\s+/u', ' ', $t));
    }
}

if (!function_exists('procedureDisplayIndex')) {
    /**
     * Normalised display name => code, built once over the whole value set.
     *
     * A term that two concepts share is dropped rather than resolved to
     * whichever came first: an ambiguous label is not a usable answer, and
     * silently picking one is how a plausible wrong code gets in.
     *
     * @return array<string,string>
     */
    function procedureDisplayIndex(): array
    {
        static $index = null;
        if ($index !== null) {
            return $index;
        }
        $seen = [];
        foreach (procedureFundus() as $code => $display) {
            $key = procedureNormaliseTerm($display);
            if ($key === '') {
                continue;
            }
            if (isset($seen[$key]) && $seen[$key] !== $code) {
                $seen[$key] = false;           // ambiguous, remember as unusable
                continue;
            }
            $seen[$key] = $seen[$key] ?? $code;
        }
        $index = array_filter($seen, static fn($c) => $c !== false);
        return $index;
    }
}

// ---------------------------------------------------------------------------
// the gate
// ---------------------------------------------------------------------------

if (!function_exists('procedureIsKnown')) {
    /** TRUE when the code is a concept of the procedure value set. */
    function procedureIsKnown(string $code): bool
    {
        return valueset_canonical_code(PROCEDURE_VALUESET, trim($code)) !== null;
    }
}

if (!function_exists('procedureDisplay')) {
    /**
     * The value set's display name for a code, or NULL when it does not know
     * it. NULL rather than the code itself, so a caller cannot mistake an
     * unknown code for a labelled one.
     */
    function procedureDisplay(string $code): ?string
    {
        $code = trim($code);
        return procedureIsKnown($code)
            ? valueset_display(PROCEDURE_VALUESET, $code)
            : null;
    }
}

if (!function_exists('procedureResolveTerm')) {
    /**
     * Resolve a display name to its concept.
     *
     * Exact match on the normalised term only. No fuzzy matching: a term the
     * value set does not carry is an answer the pipeline should drop and log,
     * not one it should approximate. Approximation is what put
     * "Peripheral oxygen saturation (observable entity)" into a procedure list.
     *
     * @return array{code:string,display:string}|null
     */
    function procedureResolveTerm(string $term): ?array
    {
        $key = procedureNormaliseTerm($term);
        if ($key === '') {
            return null;
        }
        $code = procedureDisplayIndex()[$key] ?? null;
        if ($code === null) {
            return null;
        }
        return ['code' => $code, 'display' => procedureFundus()[$code]];
    }
}

// ---------------------------------------------------------------------------
// the menu
// ---------------------------------------------------------------------------

if (!function_exists('procedureMenu')) {
    /**
     * Build the shortlist the model may choose from.
     *
     * Three sources, in this order, deduplicated by code and capped at $limit:
     *   1. PROCEDURE_MENU_SEED_TERMS, the ward procedures that are plausible
     *      whatever the admission reason.
     *   2. Concepts whose display carries a content word from $context - the
     *      admission reason and the discharge diagnosis - so the menu leans
     *      towards the case at hand.
     *   3. Nothing else. A short menu is better than a padded one: every entry
     *      is a procedure the model may claim was performed.
     *
     * @param  string[] $context  Free text, e.g. the reason and discharge displays.
     * @return array<string,string>  code => display
     */
    function procedureMenu(array $context = [], int $limit = PROCEDURE_MENU_LIMIT): array
    {
        $menu = [];

        foreach (PROCEDURE_MENU_SEED_TERMS as $term) {
            $hit = procedureResolveTerm($term);
            if ($hit !== null) {
                $menu[$hit['code']] = $hit['display'];
            } elseif (function_exists('registerMapMissing')) {
                // The seed list is maintained by hand and the value set moves.
                // Say which seed no longer resolves instead of quietly
                // shrinking the menu.
                registerMapMissing("+++ Procedure menu seed term not in "
                    . PROCEDURE_VALUESET . ": $term");
            }
        }

        $words = [];
        foreach ($context as $text) {
            foreach (explode(' ', procedureNormaliseTerm((string) $text)) as $w) {
                // Short words match everything and would flood the menu.
                if (mb_strlen($w) >= 5) {
                    $words[$w] = TRUE;
                }
            }
        }

        if ($words !== []) {
            foreach (procedureFundus() as $code => $display) {
                if (count($menu) >= $limit) {
                    break;
                }
                if (isset($menu[$code])) {
                    continue;
                }
                $key = ' ' . procedureNormaliseTerm($display) . ' ';
                foreach ($words as $w => $_) {
                    if (str_contains($key, ' ' . $w . ' ')) {
                        $menu[$code] = $display;
                        break;
                    }
                }
            }
        }

        return array_slice($menu, 0, $limit, TRUE);
    }
}

if (!function_exists('procedureMenuAsText')) {
    /**
     * The menu as the prompt carries it: one concept per line, code first.
     * Kept here rather than in the prompt so that the format the model is
     * shown and the format the pipeline parses are defined in one place.
     */
    function procedureMenuAsText(array $menu): string
    {
        $lines = [];
        foreach ($menu as $code => $display) {
            $lines[] = $code . '|' . $display;
        }
        return implode("\n", $lines);
    }
}
